    if let formError {
        MonarchInlineNotice(formError, tone: .danger)
    }
    MonarchTextField("Email", text: $email, error: emailError, isRequired: true)
        .textContentType(.username)
    MonarchPasswordInput("Password", text: $password, error: passwordError, purpose: .current, isRequired: true)
        .onSubmit(signIn)
        .overlay(alignment: .topTrailing) {
            Button("Forgot password?") {
                // Open the password reset recipe.
            }
            .buttonStyle(.monarchLink())
            .monarchTextStyle(.bodySmall)
            .frame(height: 20)
        }
    Toggle("Keep me signed in", isOn: $remembers)
        .toggleStyle(.monarchCheckbox)
    MonarchButton("Sign in", variant: .primary, isLoading: isSigningIn, fullWidth: true, action: signIn)
    HStack(spacing: theme.spacing.space1) {
        Text("New here?")
            .monarchTextStyle(.bodySmall)
            .foregroundStyle(theme.colors.textMuted)
        Button("Create an account") {
            // Open sign-up.
        }
        .buttonStyle(.monarchLink())
        .monarchTextStyle(.bodySmall)
    }
    .frame(maxWidth: .infinity)
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var email = {{email}}
@State private var password = ""
@State private var remembers = {{keepSignedIn}}
@State private var emailError: String?
@State private var passwordError: String?
@State private var formError: String?
@State private var isSigningIn = false

private func signIn() {
    let trimmed = email.trimmingCharacters(in: .whitespaces)
    emailError = trimmed.isEmpty
        ? "Enter your email."
        : (trimmed.contains("@") && trimmed.contains(".") ? nil : "Enter an email address like name@example.com.")
    passwordError = password.isEmpty ? "Enter your password." : nil
    guard emailError == nil, passwordError == nil else { return }
    formError = nil
    isSigningIn = true
    Task {
        // The app signs in. A wrong password goes in formError.
        try? await Task.sleep(for: .milliseconds(300))
        isSigningIn = false
    }
}

